pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(address caller) public {
        // keep caller wide but avoid the zero address to ensure it's an admissible fuzzed EOA
        vm.assume(caller != address(0));

        // The reference contract stores owner as the deployer (address(this) from setUp()).
        // We call the public owner() getter as the fuzzed caller (not strictly necessary, but shows variety).
        bool ok;
        try c.owner{gas: gasleft()}() returns (address o) {
            // owner() must never be the zero address in the correct contract (deployer was non-zero)
            ok = (o != address(0));
        } catch {
            ok = false;
        }

        // Single assertion: reference satisfies owner() != address(0) for all callers; mutant that returns address(0) will fail this for some input
        assertTrue(ok);
    }
}

