pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0)); }

    // fuzz the caller address to ensure we query owner() from various call contexts
    function testFuzz_property(address caller) public {
        // keep wide domain but avoid zero address for caller to be a meaningful EOA
        // (we still allow zero though; the property is about return value of owner())

        // call owner() from arbitrary caller context
        bool ok;
        address ownerAddr;
        if (caller == address(0)) {
            // directly call as test contract (deployer) when fuzz gives zero
            try c.owner() returns (address a) { ok = true; ownerAddr = a; } catch { ok = false; }
        } else {
            vm.prank(caller);
            try c.owner() returns (address a) { ok = true; ownerAddr = a; } catch { ok = false; }
        }

        // Single assertion: on the correct contract the owner() call must succeed and return non-zero.
        // (The mutant that always returns address(0) will violate this for some input)
        assertTrue(ok && ownerAddr != address(0));
    }
}

// Minimal interface shims referenced in setUp; kept minimal to satisfy types
interface IERC20 {
    function totalSupply() external view returns (uint256);
}
interface ICVXBooster {
}

