pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }

    // fuzz the caller address to show that for the reference contract owner() is
    // always the deployer (non-zero) irrespective of msg.sender; the mutant
    // returns address(0) instead, so some fuzzed callers will observe a different value
    function testFuzz_property(address caller) public {
        // keep wide domain but avoid zero address for caller to ensure a realistic EOA
        // (not strictly necessary, but keeps fuzz inputs meaningful)
        // Do not exclude values that could trigger the mutant; allow all addresses.

        // Call owner() as the fuzzed caller. We must observe only via public surface.
        // Use try/catch to capture any unexpected reverts (shouldn't revert).
        bool ok;
        address observed;
        try c.owner{gas: gasleft()}() returns (address a) {
            ok = true;
            observed = a;
        } catch {
            ok = false;
            observed = address(0);
        }

        // The reference contract always has a non-zero owner (the deployer = address(this) at setup).
        // Thus the general property: the call completes (ok == true) and returns a non-zero address equal to the deployer.
        // We assert exactly that the call succeeded and owner() is non-zero. The mutant that returns address(0)
        // will make this assertion fail for some inputs (i.e., it returns address(0) instead of deployer).
        assertTrue(ok && observed != address(0));
    }
}

