pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }

    // General rule: reference returns the stored owner (which may be address(this) initially,
    // but owner can be transferred to some other address). The mutant that hardcodes owner()
    // to return address(this) will differ whenever the stored owner != address(this).
    // We fuzz a candidate newOwner; if it is different from address(this), transferring ownership
    // to it must make c.owner() equal that newOwner in the reference, but the mutant would still
    // return address(this).
    function testFuzz_property(address newOwner) public {
        // keep wide domain but avoid zero address since transferOwnership disallows it
        if (newOwner == address(0)) return;

        // OnlyOwner functions use msg.sender == owner(); initially owner is address(this) (deployer in setUp)
        // Transfer ownership to the fuzzed newOwner using the current owner (which is this test contract)
        c.transferOwnership(newOwner);

        // Now the general invariant: owner() must return the stored owner (newOwner)
        // We'll call owner and assert it equals newOwner. This holds for the reference for ALL inputs,
        // but the mutant that returns address(this) will fail when newOwner != address(this).
        address got = c.owner();
        assertTrue(got == newOwner);
    }
}

