        // The universal property we assert: For ALL inputs, when a contract (Caller) whose deployer equals c.owner() attempts to call setRewardsRecipient, the reference contract should reject because msg.sender (Caller) != owner(); thus ok must be false for the reference.
        // The mutant that compares owner() to tx.origin would accept this call (ok==true) for some inputs; hence our assertion distinguishes them: reference must always have ok == false.
        assertTrue(!ok);
    }
}

contract Caller {
    function trySet(C c, address recipient) external returns (bool) {
        // call setRewardsRecipient via this contract; return true if call succeeded, false if reverted
        try c.setRewardsRecipient(recipient) {
            return true;
        } catch {
            return false;
        }
    }
}

