import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0)); }

    // Fuzzed parameters: ownerCaller will be the tx.origin (the EOA that initiates), proxyCaller will be the contract that calls c,
    // and recipient is the address to set as rewardsRecipient. The property: only direct calls from owner (msg.sender==owner)
    // should succeed on reference; the mutant using tx.origin will allow a proxied call from a contract where tx.origin==owner.
    function testFuzz_property(address ownerCaller, address recipient) public {
        vm.assume(ownerCaller != address(0));
        // Deploy a tiny proxy that will call c.setRewardsRecipient on behalf of tx.origin.
        CallerProxy proxy = new CallerProxy();

        // Ensure owner of c is this test contract (set in Ownable constructor). We'll transfer ownership to ownerCaller so
        // owner() == ownerCaller. Use vm.prank to call transferOwnership from current owner (this contract).
        vm.prank(address(this));
        c.transferOwnership(ownerCaller);

        // CASE: direct call by ownerCaller (EOA) should succeed on reference because msg.sender == owner()
        bool okDirect;
        vm.prank(ownerCaller);
        try c.setRewardsRecipient(recipient) {
            okDirect = true;
        } catch {
            okDirect = false;
        }

        // Reset rewardsRecipient to zero via direct owner to ensure a consistent start for proxied attempt
        if (okDirect) {
            vm.prank(ownerCaller);
            c.setRewardsRecipient(address(0));
        }

        // CASE: proxied call: we simulate an EOA ownerCaller initiating a call that goes through the proxy contract
        // The proxy will call c.setRewardsRecipient with msg.sender == proxy and tx.origin == ownerCaller.
        bool okProxied;
        // make the call as if ownerCaller is the EOA origin
        vm.prank(ownerCaller);
        try proxy.callSetRewardsRecipient(address(c), recipient) {
            okProxied = true;
        } catch {
            okProxied = false;
        }

        // The general invariant the reference satisfies for ALL inputs: a proxied call (msg.sender != owner()) MUST NOT succeed
        // Thus we assert that okProxied == false OR that direct-call success equals proxied success only when ownerCaller==proxy (impossible),
        // but to be precise: require that if the direct call failed then proxied must also fail; however the mutant will allow proxied succeed
        // when tx.origin == ownerCaller. We simplify to a single assertion: the reference ensures proxied call does not succeed.
        assertTrue(!okProxied);
    }
}

// Minimal helper proxy that forwards calls to c
contract CallerProxy {
    function callSetRewardsRecipient(address cAddr, address recipient) external {
        C(cAddr).setRewardsRecipient(recipient);
    }
}

