pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0)); }

    // fuzz param: an owner address (orig) and a recipient address (recip)
    // We will deploy a forwarding contract F that when called by orig will forward the call to c (so tx.origin == orig, msg.sender == F)
    function testFuzz_property(address orig, address recip) public {
        // keep orig non-zero to be a valid owner candidate
        vm.assume(orig != address(0));
        // do not constrain recip (allow zero too)

        // set the contract's owner to orig by transferring ownership from the default owner (this test contract)
        // currently c.owner() == address(this) because constructor of Ownable sets deployer
        // transfer ownership to orig
        c.transferOwnership(orig);

        // Deploy a simple forwarder that will forward a call to c.setRewardsRecipient
        Forwarder f = new Forwarder(c);

        // Now: two ways to call setRewardsRecipient:
        // 1) Direct call from an EOA (we simulate by vm.prank) as addr != orig should fail; only orig as msg.sender should succeed on reference.
        // 2) Call via forwarder: we simulate orig initiating the tx to forwarder (so tx.origin == orig) which then calls c (msg.sender == forwarder), this should still fail on reference because msg.sender != owner, but succeed on mutant where owner() == tx.origin is used.

        // First, sanity: direct call as orig must succeed on reference
        vm.prank(orig);
        bool okDirect = trySetRewardsRecipient(recip);
        // require that direct call by owner succeeds
        assertTrue(okDirect);

        // Now, simulate orig calling the forwarder which forwards the call to c.
        // When forwarder calls c, msg.sender == address(f), tx.origin == orig.
        // On reference contract this should revert (only msg.sender == owner allowed), so the forwarded call should fail.
        bool okForwarded = f.forwardSetRewardsRecipient{gas: gasleft()}(orig, recip);

        // Single assertion: on the reference contract the forwarded call must fail for all inputs where orig != address(f)
        // We ensure orig != address(f) to make the test logically correct (owner is not the forwarder contract)
        vm.assume(orig != address(f));
        assertTrue(!okForwarded);
    }

    // helper to try calling setRewardsRecipient and return success boolean
    function trySetRewardsRecipient(address recip) internal returns (bool) {
        bool ok;
        try c.setRewardsRecipient(recip) {
            ok = true;
        } catch {
            ok = false;
        }
        return ok;
    }
}

// Forwarder contract: when tx.origin is an EO A orig, owner can call this forwarder which will call c.setRewardsRecipient
contract Forwarder {
    C immutable target;
    constructor(C _target) {
        target = _target;
    }
    // called by orig (tx.origin == orig), forwarder will call target.setRewardsRecipient
    function forwardSetRewardsRecipient(address /*orig*/, address recip) external returns (bool) {
        bool ok;
        try target.setRewardsRecipient(recip) {
            ok = true;
        } catch {
            ok = false;
        }
        return ok;
    }
}

