pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0)); }

    // fuzzed params: an address that will act as tx.origin (owner) and an address that will be the recipient
    function testFuzz_property(address ownerAddr, address recipient) public {
        // keep addresses non-zero to be meaningful
        vm.assume(ownerAddr != address(0));
        vm.assume(recipient != address(0));

        // Make ownerAddr the owner of c by transferring ownership from deployer (address(this)) to ownerAddr
        // Only current owner (address(this)) can call transferOwnership
        c.transferOwnership(ownerAddr);

        // Deploy a forwarding helper contract that will act as msg.sender (a contract) but preserve tx.origin = ownerAddr
        Forwarder f = new Forwarder(address(c));

        // The property: in the reference contract only msg.sender == owner() can call setRewardsRecipient successfully.
        // So a call that originates from ownerAddr but is forwarded by a contract (msg.sender == Forwarder) must fail on reference.
        // We simulate a transaction where tx.origin == ownerAddr by using vm.prank(ownerAddr) when invoking the forwarder.

        // First, show that direct call from ownerAddr succeeds (baseline)
        vm.prank(ownerAddr);
        // direct call should succeed and set rewardsRecipient to recipient
        c.setRewardsRecipient(recipient);
        assertTrue(c.rewardsRecipient() == recipient);

        // Now reset to some other value to observe the forwarded attempt effect
        address other = address(0x1234);
        vm.prank(ownerAddr);
        c.setRewardsRecipient(other);
        assertTrue(c.rewardsRecipient() == other);

        // Now attempt forwarded call: tx.origin == ownerAddr, but msg.sender == address(f)
        vm.prank(ownerAddr);
        bool ok;
        try f.forwardSetRewardsRecipient(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal rule we assert: when msg.sender != owner() (here msg.sender == address(f)), the reference contract MUST NOT allow setRewardsRecipient to be executed successfully even if tx.origin == ownerAddr.
        // Therefore ok must be false for the reference contract. This will fail on the mutant where owner() is compared to tx.origin instead of msg.sender.
        assertTrue(!ok);
    }
}

// Forwarder contract: a simple contract that forwards calls to C; when invoked by ownerAddr as tx.origin,
// msg.sender inside C will be this Forwarder contract (address(this)), enabling the mutant behavior.
contract Forwarder {
    C c;
    constructor(address _c) { c = C(_c); }

    function forwardSetRewardsRecipient(address recipient) external {
        // forward the call; msg.sender to C will be this contract, tx.origin will be original EOA
        c.setRewardsRecipient(recipient);
    }
}

